test('D1 - Ball should bounce (top/bottom)', () => {
  const state = createState(1);
  state.ball.x = 100; 
  state.ball.y = 40; 
  state.ball.vx = 0;
  state.ball.vy = 100; 
  state.bricks[0].x = 80;
  state.bricks[0].y = 48;
  state.bricks[0].w = 72;
  state.bricks[0].h = 20;
  state.bricks[0].alive = true;

  const initialVy = state.ball.vy;
  handleBrickCollisions(state);
  assert.notStrictEqual(state.ball.vy, initialVy, 'Ball should have bounced off top/bottom');
});

test('D2 - Ball should bounce (sides)', () => {
  const state = createState(1);
  state.ball.x = 70; 
  state.ball.y = 60; 
  state.ball.vx = 100;
  state.ball.vy = 0; 
  state.bricks[0].x = 80;
  state.bricks[0].y = 48;
  state.bricks[0].w = 72;
  state.bricks[0].h = 20;
  state.bricks[0].alive = true;

  const initialVx = state.ball.vx;
  handleBrickCollisions(state);
  assert.notStrictEqual(state.ball.vx, initialVx, 'Ball should have bounced off sides');
});

test('D3 - Ghost collision (multiple bricks)', () => {
  const state = createState(1);
  state.ball.x = 100; 
  state.ball.y = 40; 
  state.ball.vx = 0;
  state.ball.vy = 100; 

  // Two bricks that the ball overlaps simultaneously
  state.bricks[0] = { x: 80, y: 48, w: 72, h: 20, alive: true };
  state.bricks[1] = { x: 160, y: 48, w: 72, h: 20, alive: true };
  // Ball radius is 7, so it can span 14.
  // If ball.x is 153, it's at 146...160.
  state.ball.x = 153; 

  const initialVy = state.ball.vy;
  handleBrickCollisions(state);

  // If it bounces off both, and we just flip vy, it'll be vy = -(-vy) = vy.
  // We expect it to still be bouncing (vy should be inverted).
  assert.notStrictEqual(state.ball.vy, initialVy, 'Ball should still bounce even if hitting two bricks');
});

test('D4 - Tunneling', () => {
  const state = createState(1);
  state.ball.x = 100;
  state.ball.y = 40;
  state.ball.vx = 0;
  state.ball.vy = 1000; // Very fast

  state.bricks[0] = { x: 80, y: 48, w: 72, h: 20, alive: true };

  // In a real game, we use step().
  // If the ball is at 40 and moves 1000 * 0.05 = 50, it will be at 90.
  // The brick is at 48..68. 
  // The ball's previous position was 40. 
  // We need to check if it "passed through" the brick.

  const dt = 0.05;
  const prevY = state.ball.y;
  step(state, dt); // Now ball.y = 90

  // After step, we check collision in frame().
  // Since the ball is at 90, and the brick is at 48..68, collides() will be false.
  const collided = collides(state.ball, state.bricks[0]);

  assert.strictEqual(collided, true, 'Ball should have collided even with high velocity (tunneling)');
});

