export function resolveBrickCollisions(state) {
  const { ball } = state;
  let collided = false;

  for (const brick of state.bricks) {
    if (!brick.alive) continue;

    if (collides(ball, brick)) {
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
      collided = true;

      // Find the overlap on each axis
      const overlapX = Math.min(ball.x + ball.r - brick.x, brick.x + brick.w - (ball.x - ball.r));
      const overlapY = Math.min(ball.y + ball.r - brick.y, brick.y + brick.h - (ball.y - ball.r));

      if (overlapX < overlapY) {
        // Side hit
        ball.vx = -ball.vx;
        // Reposition to avoid sticking
        if (ball.vx > 0) ball.x = brick.x - ball.r;
        else ball.x = brick.x + brick.w + ball.r;
      } else {
        // Top/Bottom hit
        ball.vy = -ball.vy;
        // Reposition to avoid sticking
        if (ball.vy > 0) ball.y = brick.y - ball.r;
        else ball.y = brick.y + brick.h + ball.r;
      }

      // Only one bounce per frame to avoid ghost collisions
      break; 
    }
  }
}
